/// The copies Clipboard History never keeps: those an app marks as secret or short-lived, and those made in an app
/// the user told it to ignore.
nonisolated enum PrivacyFilter {
    /// Marker types of the nspasteboard.org conventions (concealed, transient, auto-generated), followed by password
    /// managers and other apps, plus the older private markers some of them still write.
    static let markerTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
        "net.antelle.keeweb",
    ]

    /// Ignored until the user changes the list in Settings: password managers and the keychain, whose copies are
    /// secrets even when they carry no marker.
    static let defaultIgnoredApps = [
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.bitwarden.desktop",
        "org.keepassxc.keepassxc",
    ]

    /// Names for the default apps, shown in Settings while the app is not installed.
    static let defaultAppNames = [
        "com.apple.keychainaccess": "Keychain Access",
        "com.apple.Passwords": "Passwords",
        "com.1password.1password": "1Password",
        "com.agilebits.onepassword7": "1Password 7",
        "com.bitwarden.desktop": "Bitwarden",
        "org.keepassxc.keepassxc": "KeePassXC",
    ]

    static func isMarkedPrivate(_ types: some Sequence<String>) -> Bool {
        types.contains { markerTypes.contains($0) }
    }

    static func ignores(bundleID: String?, in ignoredApps: [String]) -> Bool {
        guard let bundleID else { return false }
        return ignoredApps.contains { $0.caseInsensitiveCompare(bundleID) == .orderedSame }
    }
}
